  Section Main.
    Variables (fx : FPState) (A0 : AS MI) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model).
    Variables (sp st1 st2 obj1 bl1 bc1 obj2 bl2 bc2 : Z) (ents1 ents2 : list (Z * (Z * V))) (K : TSet).
    Variables (wra w8 w9 w18 : word).
    Hypothesis Hobj1 : obj1 = st1 + 88.
    Hypothesis Hobj2 : obj2 = st2 + 88.
    Hypothesis AI0 : ainv MI A0 M0 model0.
    Hypothesis MS0 : mstd model0.
    Hypothesis ROC0 : img_ro_clear L M0.
    Hypothesis R0sp : getr R0 2%bv = Z_to_bv 64 (sp - 32).
    Hypothesis R0gp : getr R0 3%bv = Z_to_bv 64 (ly_gp L).
    Hypothesis R0tp : getr R0 4%bv = Z_to_bv 64 (ly_tp L).
    Hypothesis R0s0 : getr R0 8%bv = Z_to_bv 64 st1.
    Hypothesis R0s1 : getr R0 9%bv = Z_to_bv 64 st2.
    Hypothesis SPF : sp mod 16 = 0 /\ alloc_ceiling + (32 + DEL_STACK) <= sp /\ sp < 2 ^ 47 /\ 0x122000 <= sp - (32 + DEL_STACK).
    Hypothesis Hdef0 : defined M0 (sp - 32 - DEL_STACK) (32 + DEL_STACK).
    Hypothesis Hwin0 : forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A0 a.
    Hypothesis U1 : umapx MI NS nval A0 M0 obj1 bl1 bc1 ents1.
    Hypothesis U2 : umapx MI NS nval A0 M0 obj2 bl2 bc2 ents2.
    Hypothesis AS1 : above_sp MI A0 sp obj1 40.
    Hypothesis AS2 : above_sp MI A0 sp obj2 40.
    Hypothesis AP12 : apart obj1 40 obj2 40.
    Hypothesis DJ : forall b, In b (map fst (umap_blocks NS bl1 bc1 ents1)) -> ~ In b (map fst (umap_blocks NS bl2 bc2 ents2)).
    Definition FOOT (a : Z) : Prop := umap_foot NS obj1 bl1 bc1 ents1 a \/ umap_foot NS obj2 bl2 bc2 ents2 a.
    Definition W : Z * Z := (sp - (32 + DEL_STACK), sp).

    #[local] Notation FOOT1 := (umap_foot NS obj1 bl1 bc1 ents1).
    #[local] Notation FOOTB := (fun a => umap_foot NS obj1 bl1 bc1 ents1 a \/ (obj2 <= a < obj2 + 40)).

    Definition frame (M : mem) : Prop :=
      cell8 SEGS M (sp - 8) (bv_unsigned wra) /\ cell8 SEGS M (sp - 16) (bv_unsigned w8)
      /\ cell8 SEGS M (sp - 24) (bv_unsigned w9) /\ cell8 SEGS M (sp - 32) (bv_unsigned w18).

    Definition base_ok (R : bvmap 5 word) : Prop :=
      getr R 2%bv = Z_to_bv 64 (sp - 32) /\ getr R 3%bv = Z_to_bv 64 (ly_gp L) /\ getr R 4%bv = Z_to_bv 64 (ly_tp L)
      /\ getr R 8%bv = Z_to_bv 64 st1 /\ getr R 9%bv = Z_to_bv 64 st2
      /\ forall r, In r [19; 20; 21; 22; 23; 24; 25; 26; 27]%bv -> getr R r = getr R0 r.

    Lemma base_pres : forall R R', base_ok R -> pres PRES R R' -> base_ok R'.
Proof using L R0 sp st1 st2.
