    Lemma phaseD : forall fr A M model R,
      ainv MI A M model -> mstd model -> m_fs model = m_fs model0 -> m_fds model = m_fds model0 ->
      base_ok R -> frame M ->
      defined M (sp - 32 - DEL_STACK) (32 + DEL_STACK) -> (forall a, zwin (sp - 32 - DEL_STACK) sp a -> ~ owned MI A a) ->
      eff MI A0 A M0 M W FOOT -> lapply (live MI A0) (free_ops bl1 bc1 ents1) (live MI A) ->
      umapx MI NS nval A M obj1 bl2 bc2 ents2 -> umapx MI NS nval A M obj2 0 0 [] ->
